package vn.svframe.mythiclibfabric.runtime.script;
import java.util.*;
public final class ScriptLineParser {public record Call(String name,Map<String,String> params){}private ScriptLineParser(){}public static Call parse(String raw){String s=raw.trim();if((s.startsWith("'")&&s.endsWith("'"))||(s.startsWith("\"")&&s.endsWith("\"")))s=s.substring(1,s.length()-1);int b=s.indexOf('{');if(b<0)return new Call(s.toLowerCase(Locale.ROOT),Map.of());int e=matchingEnd(s,b);if(e<0)e=s.length()-1;String name=s.substring(0,b).trim().toLowerCase(Locale.ROOT);Map<String,String> out=new LinkedHashMap<>();for(String part:split(s.substring(b+1,e))){int eq=findEq(part);if(eq<0){if(!part.isBlank())out.put(part.trim(),"true");}else out.put(part.substring(0,eq).trim().toLowerCase(Locale.ROOT),unquote(part.substring(eq+1).trim()));}return new Call(name,Map.copyOf(out));}
 private static int matchingEnd(String s,int b){int d=0;char q=0;for(int i=b;i<s.length();i++){char c=s.charAt(i);if(q!=0){if(c==q&&(i==0||s.charAt(i-1)!='\\'))q=0;continue;}if(c=='\''||c=='\"')q=c;else if(c=='{')d++;else if(c=='}'&&--d==0)return i;}return-1;}private static int findEq(String s){char q=0;int d=0;for(int i=0;i<s.length();i++){char c=s.charAt(i);if(q!=0){if(c==q&&(i==0||s.charAt(i-1)!='\\'))q=0;}else if(c=='\''||c=='\"')q=c;else if(c=='{'||c=='[')d++;else if(c=='}'||c==']')d--;else if(c=='='&&d==0)return i;}return-1;}private static List<String> split(String s){List<String>r=new ArrayList<>();char q=0;int d=0,st=0;for(int i=0;i<s.length();i++){char c=s.charAt(i);if(q!=0){if(c==q&&(i==0||s.charAt(i-1)!='\\'))q=0;}else if(c=='\''||c=='\"')q=c;else if(c=='{'||c=='[')d++;else if(c=='}'||c==']')d--;else if((c==';'||c==',')&&d==0){r.add(s.substring(st,i).trim());st=i+1;}}r.add(s.substring(st).trim());return r;}private static String unquote(String s){if(s.length()>1&&((s.startsWith("\"")&&s.endsWith("\""))||(s.startsWith("'")&&s.endsWith("'"))))return s.substring(1,s.length()-1);return s;}}
